const crypto = require('crypto');
const target = '62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac';
const words = ['quarterly','Quarterly','QUARTERLY','report','Report','REPORT','2026'];
const seps = ['', ' ', '-', '_', '--', '__', '-_', '_-'];
let count=0;
for (const a of words) for (const b of words) for (const c of words) {
  if (a==='2026' && b==='2026') continue;
  for (const s1 of seps) for (const s2 of seps) {
    const str = a+s1+b+s2+c;
    count++;
    const d = crypto.createHash('sha256').update(str,'utf8').digest('hex');
    if (d===target) console.log('MATCH', JSON.stringify(str), str.includes('_2026'));
  }
}
console.error('checked', count);
